"""DDL for metadata-created isolated test schemas; production uses frozen migration."""
D6_GUARD_SQL = "CREATE FUNCTION erp_d6_evidence_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE prior_id integer; actor_id integer; source payroll_d6_evidence; \nBEGIN\n IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'D6 evidence and reviews are immutable'; END IF;\n PERFORM id FROM companies WHERE id=NEW.company_id FOR UPDATE;\n actor_id := CASE WHEN TG_TABLE_NAME='payroll_d6_evidence_reviews' THEN (to_jsonb(NEW)->>'reviewed_by')::integer ELSE (to_jsonb(NEW)->>'created_by')::integer END;\n IF NOT EXISTS(SELECT 1 FROM users u JOIN user_company_roles ur ON ur.user_id=u.id JOIN role_permissions rp ON rp.role_id=ur.role_id JOIN permissions p ON p.id=rp.permission_id\n  WHERE u.id=actor_id AND u.is_active AND ur.company_id=NEW.company_id AND ur.is_active AND p.name='employees.manage') THEN\n  RAISE EXCEPTION 'D6 actor lacks active company permission';\n END IF;\n IF TG_TABLE_NAME='payroll_d6_evidence_reviews' THEN\n  SELECT * INTO source FROM payroll_d6_evidence WHERE company_id=NEW.company_id AND id=NEW.evidence_id;\n  IF source.id IS NULL OR source.created_by=NEW.reviewed_by THEN RAISE EXCEPTION 'Independent D6 reviewer required'; END IF;\n  IF NEW.decision='approved' THEN\n   SELECT e.id INTO prior_id FROM payroll_d6_evidence e JOIN payroll_d6_evidence_reviews r ON r.company_id=e.company_id AND r.evidence_id=e.id\n    WHERE e.company_id=source.company_id AND e.payroll_period_id=source.payroll_period_id AND e.employment_contract_id=source.employment_contract_id AND r.decision='approved'\n    ORDER BY e.revision DESC LIMIT 1;\n   IF source.supersedes_id IS DISTINCT FROM prior_id THEN RAISE EXCEPTION 'Stale D6 correction'; END IF;\n  END IF;\n ELSE\n  IF (NEW.payload->>'payroll_period_id')::integer IS DISTINCT FROM NEW.payroll_period_id\n    OR (NEW.payload->>'employment_contract_id')::integer IS DISTINCT FROM NEW.employment_contract_id\n    OR (NEW.payload->>'supersedes_id')::integer IS DISTINCT FROM NEW.supersedes_id\n    OR jsonb_typeof(NEW.payload->'applies') IS DISTINCT FROM 'boolean'\n    OR jsonb_typeof(NEW.payload->'intervals') IS DISTINCT FROM 'array' THEN\n    RAISE EXCEPTION 'Invalid D6 factual payload identity';\n  END IF;\n  IF (NEW.payload->>'applies')::boolean IS DISTINCT FROM (jsonb_array_length(NEW.payload->'intervals')>0) THEN\n    RAISE EXCEPTION 'D6 applicability and intervals disagree';\n  END IF;\n  IF NEW.revision<>(SELECT COALESCE(MAX(e.revision),0)+1 FROM payroll_d6_evidence e WHERE e.company_id=NEW.company_id AND e.payroll_period_id=NEW.payroll_period_id AND e.employment_contract_id=NEW.employment_contract_id) THEN\n    RAISE EXCEPTION 'D6 revision sequence mismatch';\n  END IF;\n  IF NEW.supersedes_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM payroll_d6_evidence e JOIN payroll_d6_evidence_reviews r ON r.company_id=e.company_id AND r.evidence_id=e.id\n   WHERE e.id=NEW.supersedes_id AND e.company_id=NEW.company_id AND e.payroll_period_id=NEW.payroll_period_id AND e.employment_contract_id=NEW.employment_contract_id AND e.revision<NEW.revision AND r.decision='approved') THEN\n    RAISE EXCEPTION 'Invalid D6 correction predecessor';\n  END IF;\n END IF;\n RETURN NEW;\nEND $$"
